import matplotlib.pyplot as pltfrom sys import stdoutfrom models import henonfrom mpmath import mpimport osimport datetimemp.dps = 24####  Фазовый портрет динамической системы###a = mp.mpf('1.43')b = mp.mpf('0.5')c = mp.mpf('-1.7594137')x = [mp.mpf('0.1'), mp.mpf('0.1'), mp.mpf('0.1')]# Списки для данныхfase_port_x_0, fase_port_y_0, fase_port_z_0 = [], [], []fase_port_x_1, fase_port_y_1, fase_port_z_1 = [], [], []fase_port_x_2, fase_port_y_2, fase_port_z_2 = [], [], []fase_port_x_3, fase_port_y_3, fase_port_z_3 = [], [], []# Транзиентfor i in range(1_000_000):    x = henon(x, a, b, c)# Основной циклn = M = k = l = 0while k != 10_000:    stdout.write("\r%d" % k)    stdout.flush()    x = henon(x, a, b, c)    fase_port_x_0.append(x[0])    fase_port_y_0.append(x[1])    fase_port_z_0.append(x[2])    n += 1    if (-0.38 < x[0] < -0.36) and (-0.414 < x[1] < -0.405):        fase_port_x_1.append(x[0])        fase_port_y_1.append(x[1])        fase_port_z_1.append(x[2])        M += 1    if (-0.381 < x[0] < -0.378) and (-0.4088 < x[1] < -0.408):        fase_port_x_2.append(x[0])        fase_port_y_2.append(x[1])        fase_port_z_2.append(x[2])        k += 1    # if (-0.40074 < x[0] < -0.40069) and (-0.397155 < x[1] < -0.397115):    #     fase_port_x_3.append(x[0])    #     fase_port_y_3.append(x[1])    #     fase_port_z_3.append(x[2])    #     l += 1print('\n', n, M, k, l, sep='\n')# def convert_to_float(lst):#     return [float(val) for val in lst]# --- НАСТРОЙКА СОХРАНЕНИЯ В ПАПКУ ---# Вариант 1: Создаем папку в текущей директорииoutput_dir = 'Portraits'os.makedirs(output_dir, exist_ok=True)# Вариант 2: Создаем папку с датой и параметрами (для организации экспериментов)# timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")# params_str = f"a_{float(a):.2f}_b_{float(b):.2f}_c_{float(c):.4f}"# output_dir = os.path.join('phase_portraits', f"{params_str}_{timestamp}")# os.makedirs(output_dir, exist_ok=True)print(f"📁 Картинки будут сохранены в: {os.path.abspath(output_dir)}")# Настройки для высокого качестваplt.rcParams['figure.dpi'] = 300plt.rcParams['savefig.dpi'] = 600plt.rcParams['font.size'] = 12plt.rcParams['lines.antialiased'] = Trueplt.rcParams['patch.antialiased'] = True# Данные для графиковfigures_data = [    (fase_port_x_0, fase_port_y_0, 0.1),    (fase_port_x_1, fase_port_y_1, 0.3),    (fase_port_x_2, fase_port_y_2, 0.3),    (fase_port_x_3, fase_port_y_3, 0.3),]names = ['full', 'zoom1', 'zoom2', 'zoom3']for idx, ((x_data, y_data, ms), name) in enumerate(zip(figures_data, names)):    if not x_data:        print(f"⚠️ График {idx} пуст, пропускаем")        continue    fig, ax = plt.subplots()    # x_float = convert_to_float(x_data)    # y_float = convert_to_float(y_data)    ax.plot(x_data, y_data, 'g.', ms=0.15)    ax.set_title(f'A = {a}, B = {b}, C = {c}')    ax.grid()    ax.set_xlabel('X')    ax.set_ylabel('Y')    # ax.set_aspect('equal', adjustable='box')    # --- СОХРАНЯЕМ В ПАПКУ ---    # PNG с высоким DPI    filepath_png = os.path.join(output_dir, f'phase_portrait_{name}.png')    plt.savefig(filepath_png,                dpi=600,                bbox_inches='tight',                facecolor='white',                edgecolor='none')    print(f"✅ Сохранен PNG: {filepath_png}")    plt.close()print(f"\n🎉 Все изображения сохранены в папку:\n{os.path.abspath(output_dir)}")